import re

_GENDER_TOKEN_RE = re.compile(r"\[\[([^|\]]+)\|([^\]]+)\]\]")

def personalize_text(text: str, gender: str | None) -> str:
    """Рендерит токены [[мужская форма|женская форма]]. Без пола оставляет нейтрально первую форму."""
    if not isinstance(text, str):
        return text
    use_female = gender == "female"
    return _GENDER_TOKEN_RE.sub(lambda m: m.group(2) if use_female else m.group(1), text)

